#include <stdio.h>#include <stdlib.h>#include <string.h>#include <ctype.h>// Estructura para guardar la palabra en inglés y su traduccióntypedef struct {    char ingles[20];    char espanol[20];} Palabra;// Diccionario de palabras reservadasPalabra diccionario[] = {    {"auto", "auto"}, {"break", "romper"}, {"case", "caso"}, {"char", "caracter"},    {"const", "constante"}, {"continue", "continuar"}, {"default", "defecto"}, {"do", "hacer"},    {"double", "doble"}, {"else", "sino"}, {"enum", "enumeracion"}, {"extern", "externo"},    {"float", "flotante"}, {"for", "para"}, {"goto", "ir_a"}, {"if", "si"},    {"inline", "en_linea"}, {"int", "entero"}, {"long", "largo"}, {"register", "registro"},    {"restrict", "restringir"}, {"return", "retornar"}, {"short", "corto"}, {"signed", "con_signo"},    {"sizeof", "tamano_de"}, {"static", "estatico"}, {"struct", "estructura"}, {"switch", "cambiar"},    {"typedef", "definir_tipo"}, {"union", "union"}, {"unsigned", "sin_signo"}, {"void", "vacio"},    {"volatile", "volatil"}, {"while", "mientras"}};int num_palabras = sizeof(diccionario) / sizeof(diccionario[0]);int main() {    // 1. CÓDIGO C DE PRUEBA (Simulando la lectura de un archivo)    const char* codigo_original =         "#include <stdio.h>\n"        "int main() {\n"        "    int x = 10;\n"        "    if (x > 5) {\n"        "        while (x > 0) {\n"        "            x--;\n"        "        }\n"        "        return 1;\n"        "    }\n"        "    return 0;\n"        "}\n";    printf("--- CODIGO ORIGINAL EN C ---\n%s\n", codigo_original);    // 2. CARGA EN MEMORIA DINÁMICA (Requisito del PDF)    int len = strlen(codigo_original);    char* memoria_dinamica = (char*)malloc((len + 1) * sizeof(char));    if (memoria_dinamica == NULL) {        printf("Error al asignar memoria.\n");        return 1;    }    strcpy(memoria_dinamica, codigo_original); // Copiamos el texto a la memoria dinámica    // 3. TRADUCCIÓN    printf("\n--- CODIGO TRADUCIDO A ESPANOL ---\n");        char* ptr = memoria_dinamica;    while (*ptr != '\0') {        // Si es una letra o guion bajo, extraemos la palabra        if (isalpha(*ptr) || *ptr == '_') {            char palabra[50];            int i = 0;            while (isalnum(*ptr) || *ptr == '_') {                palabra[i++] = *ptr++;            }            palabra[i] = '\0';            // Buscamos la palabra en el diccionario            int traducida = 0;            for (int j = 0; j < num_palabras; j++) {                if (strcmp(palabra, diccionario[j].ingles) == 0) {                    printf("%s", diccionario[j].espanol);                    traducida = 1;                    break;                }            }            // Si no es palabra reservada, se queda igual            if (!traducida) {                printf("%s", palabra);            }        } else {            // Si no es letra (espacios, paréntesis, etc), se imprime igual            printf("%c", *ptr++);        }    }    printf("\n");    // 4. LIBERAR MEMORIA    free(memoria_dinamica);    return 0;}